58	};
59	
60	const MOCK_AUTH_COOKIE = 'mock-auth-state';
61	const MOCK_AUTH_USER_COOKIE = 'mock-auth-user';
62	
63	const defaultMockUsers = {
64	    user: {
65	        id: 'test-user-id',
66	        name: 'Test User',
67	        email: 'testuser@example.com',
68	        role: 'user' as const,
69	        playerId: 1,
