91	    },
92	};
93	
94	const parseCookies = (cookieHeader: string | null): Record<string, string> => {
95	    if (!cookieHeader) return {};
96	    return cookieHeader
97	        .split(';')
98	        .reduce<Record<string, string>>((acc, cookie) => {
99	            const trimmed = cookie.trim();
100	            if (!trimmed) return acc;
101	            const [name, ...rest] = trimmed.split('=');
102	            if (!name) return acc;
103	            acc[name] = decodeURIComponent(rest.join('='));
104	            return acc;
105	        }, {});
106	};
107	
108	const resolveMockAuth = (cookieHeader: string | null) => {
109	    const cookies = parseCookies(cookieHeader);
110	    const role = cookies[MOCK_AUTH_COOKIE] as MockAuthState | undefined;
111	    const userRaw = cookies[MOCK_AUTH_USER_COOKIE];
112	    let userOverride: MockAuthUser | null = null;
113	    if (userRaw) {
114	        try {
115	            userOverride = JSON.parse(userRaw) as MockAuthUser;
116	        } catch {
117	            userOverride = null;
118	        }
119	    }
120	
121	    const effectiveRole = role === 'admin' || role === 'user' ? role : 'none';
122	    if (effectiveRole === 'none') {
123	        return { role: 'none' as const, user: null };
124	    }
125	
126	    const baseUser = defaultMockUsers[effectiveRole];
127	    const user = {
128	        ...baseUser,
129	        ...userOverride,
130	        role: effectiveRole,
131	    };
132	    return { role: effectiveRole, user };
133	};
