143	
144	        if (role === 'none') {
145	            document.cookie = `${MOCK_AUTH_COOKIE}=; path=/; expires=Thu, 01 Jan 1970 00:00:00 GMT`;
146	            document.cookie = `${MOCK_AUTH_USER_COOKIE}=; path=/; expires=Thu, 01 Jan 1970 00:00:00 GMT`;
147	            return;
148	        }
149	
